// Кейс .qa/tests/admin-plans/AP-10. Две роли: admin назначает — «בדיקה» видит без перезагрузки.
// ПИШЕТ данные на проде: только аккаунт «בדיקה», отмена назначения в finally. Не @prod-safe.
import { test, expect } from '../../fixtures';
import { setLanguage, openPlansTab, targetRow, dialogFields, choosePlan, revokeIfAssigned, isoDate, enDate } from './plans-helpers';

// Приложение перечитывает назначение раз в 60 с (комментарий программиста #6eed7c73); запас до 90 с.
const PROPAGATION_MS = 90_000;

test.describe('Admin Panel — Plans', () => {
  test('Plan assigned by admin reaches «בדיקה» without reload, revoke takes it back #ca557707 @desktop @writes', async ({ asUser }) => {
    test.setTimeout(420_000);
    const admin = await asUser('admin');
    const user = await asUser('user');
    await setLanguage(admin, 'en');
    await setLanguage(user, 'en');

    await revokeIfAssigned(admin, 'QA-AUTO pre-clean #ca557707');

    const aiLink = user.getByRole('link', { name: 'AI', exact: true });

    try {
      // 1. До назначения у пользователя нет AI
      await user.goto('/dashboard');
      await expect(user.getByRole('link', { name: 'Jobs', exact: true })).toBeVisible();
      await expect(aiLink).toHaveCount(0);

      // 2. Admin назначает Pro Tech
      await openPlansTab(admin);
      const row = await targetRow(admin);
      await row.getByRole('button', { name: 'Assign plan', exact: true }).click();
      const f = dialogFields(admin);
      await choosePlan(admin, f.plan, 'Pro Tech');
      await f.until.fill(isoDate(30));
      await f.reason.fill('QA-AUTO visible-to-user #ca557707');
      await f.save.click();
      await expect(f.dialog).toBeHidden();

      // 3. У пользователя AI появляется без перезагрузки (S-15 AC 04; ≤60 с по комментарию)
      await expect(aiLink).toBeVisible({ timeout: PROPAGATION_MS });

      // 4. Billing: Pro Tech и бейдж «Granted by Techory until …»
      await user.goto('/billingsubscription');
      await expect(user.getByText('Pro Tech').first()).toBeVisible();
      await expect(user.getByText(`Granted by Techory until ${enDate(30)}`)).toBeVisible();

      // 5. Admin отменяет
      await user.goto('/dashboard');
      await expect(aiLink).toBeVisible();
      await revokeIfAssigned(admin, 'QA-AUTO revoke #ca557707');

      // 6. У пользователя AI пропадает без перезагрузки
      await expect(aiLink).toHaveCount(0, { timeout: PROPAGATION_MS });
    } finally {
      await revokeIfAssigned(admin, 'QA-AUTO cleanup #ca557707');
    }
  });
});
